/* Build the browser copy of satori that src/assets/js/share/local-card.js
 * loads when someone clicks Download PNG on a custom-text result.
 *
 * Run BY HAND, not on every build:
 *
 *     npm run og-bundle
 *
 * and commit what it writes. The three outputs are vendored artefacts in
 * exactly the way src/assets/fonts/og/*.ttf are: produced once by a tool
 * that is not part of the site's build, checked in, and regenerated only
 * when the upstream version changes. Cloudflare Pages runs Eleventy, not
 * npm scripts (see eleventy.config.js's eleventy.after), so nothing here
 * may be a build step.
 *
 * Why a bundler at all, in a project that has none:
 *
 *   node_modules/satori/dist/index.js is ESM, but it externalises its
 *   eleven npm dependencies -- `import "linebreak"`, `import "fflate"`,
 *   `import "harfbuzzjs"` and so on. A browser cannot resolve a bare
 *   specifier, and several of those packages are CommonJS, so no import
 *   map rescues it either. esbuild is already a devDependency; this is
 *   the only place it runs.
 *
 * Outputs:
 *   src/assets/vendor/satori/satori.browser.js   the bundle
 *   src/assets/vendor/satori/hb.wasm             HarfBuzz, copied verbatim
 *   src/assets/vendor/licenses/satori-bundle-LICENSES.txt
 *
 * The licence file is assembled from esbuild's metafile, so it names
 * every package whose code actually ended up in the bundle rather than
 * whatever someone remembered to list.
 */
import { build } from "esbuild";
import { readFile, writeFile, mkdir, copyFile, stat } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(__dirname, "..");
const NM = join(ROOT, "node_modules");
const OUT_DIR = join(ROOT, "src", "assets", "vendor", "satori");
const LIC_DIR = join(ROOT, "src", "assets", "vendor", "licenses");
const OUT_JS = join(OUT_DIR, "satori.browser.js");
const OUT_WASM = join(OUT_DIR, "hb.wasm");
const OUT_LIC = join(LIC_DIR, "satori-bundle-LICENSES.txt");

await mkdir(OUT_DIR, { recursive: true });
await mkdir(LIC_DIR, { recursive: true });

const result = await build({
  entryPoints: [join(ROOT, "scripts", "lib", "satori-browser-entry.js")],
  bundle: true,
  minify: true,
  format: "esm",
  platform: "browser",
  target: "es2022",
  legalComments: "none",      // the licences travel as a file, see below
  metafile: true,
  alias: {
    /* satori's HarfBuzz import, re-pointed at a wasm URL the site serves. */
    harfbuzzjs: join(ROOT, "scripts", "lib", "harfbuzz-browser.js"),
    /* harfbuzzjs's emscripten loader requires("fs") inside a branch that
       only runs under Node. Unreachable in a browser, still has to resolve. */
    fs: join(ROOT, "scripts", "lib", "empty-module.js"),
  },
  outfile: OUT_JS,
});

await copyFile(join(NM, "harfbuzzjs", "hb.wasm"), OUT_WASM);

/* ── licences, from what actually got bundled ──────────────────────── */
/* Matched on the path STRING, not against a resolved node_modules
   directory: in a git worktree node_modules is a symlink to the main
   checkout's, esbuild reports the resolved path, and relative() then
   says "..". That silently produced a licence file naming zero
   packages. */
const pkgs = new Set();
for (const input of Object.keys(result.metafile.inputs)) {
  const at = input.lastIndexOf("node_modules/");
  if (at === -1) continue;                            // our own source
  const parts = input.slice(at + "node_modules/".length).split("/");
  pkgs.add(parts[0].startsWith("@") ? `${parts[0]}/${parts[1]}` : parts[0]);
}

const LICENSE_NAMES = ["LICENSE", "LICENSE.md", "LICENSE.txt", "LICENCE", "license", "license.md", "LICENSE-MIT"];
const chunks = [];
const missing = [];
for (const name of [...pkgs].sort()) {
  let meta = {};
  try { meta = JSON.parse(await readFile(join(NM, name, "package.json"), "utf8")); } catch {}
  let text = null;
  for (const f of LICENSE_NAMES) {
    try { text = await readFile(join(NM, name, f), "utf8"); break; } catch {}
  }
  const header = `${"=".repeat(72)}\n${name} ${meta.version || ""} — ${meta.license || "licence not declared in package.json"}\n${meta.homepage || meta.repository?.url || ""}\n${"=".repeat(72)}\n`;
  if (!text) missing.push(name);
  chunks.push(header + (text ? `\n${text.trim()}\n` : "\n(No licence file ships in this package. The SPDX id above is what its package.json declares.)\n"));
}

const preamble = `Licences for src/assets/vendor/satori/satori.browser.js
${"-".repeat(72)}

This file is generated by scripts/build-og-browser-bundle.mjs from
esbuild's metafile: every package listed below has code in the bundle.

hb.wasm in this directory is HarfBuzz itself, built by the harfbuzzjs
project; its licence is the harfbuzzjs entry below.

satori is MPL-2.0, which is a per-FILE copyleft: the bundle is an
Executable Form, and MPL 2.0 section 3.2 asks that recipients be told
where the Source Code Form is. It is the published npm package
\`satori@${JSON.parse(await readFile(join(NM, "satori", "package.json"), "utf8")).version}\`
and its repository, both named in satori's entry below. No satori file
has been modified; the only build-time change is the alias in
scripts/build-og-browser-bundle.mjs that points its \`harfbuzzjs\` import
at scripts/lib/harfbuzz-browser.js, which is this project's own MIT code.

`;
await writeFile(OUT_LIC, preamble + chunks.join("\n"));

const sizeOf = async (p) => (await stat(p)).size;
const kb = (n) => `${(n / 1024).toFixed(1)} KB`;
console.log(`satori.browser.js  ${kb(await sizeOf(OUT_JS))}`);
console.log(`hb.wasm            ${kb(await sizeOf(OUT_WASM))}`);
console.log(`LICENSES.txt       ${kb(await sizeOf(OUT_LIC))}  (${pkgs.size} packages)`);
if (missing.length) console.log(`note: no licence FILE found for: ${missing.join(", ")} — the SPDX id from package.json is recorded instead`);
